import re

def handle(query, state):
    """
    Simulates a PDF report generator that accepts a `template` parameter.
    The template may contain command substitutions of the form $(cmd [arg])
    which are evaluated against the in-memory filesystem in state['files'].
    Supported commands: echo, cat, ls.
    """
    template = (query.get('template') or [''])[0]
    files = state.get('files', {})

    def _exec_cmd(cmd_str):
        # Parse the command string: first token is the command, rest are args
        parts = cmd_str.strip().split()
        if not parts:
            return ''
        cmd = parts[0]
        args = parts[1:]
        if cmd == 'echo':
            return ' '.join(args)
        elif cmd == 'cat':
            if not args:
                return ''
            path = args[0]
            return files.get(path, f'cat: {path}: No such file')
        elif cmd == 'ls':
            target = args[0] if args else '/'
            # List files whose path starts with target
            results = [p for p in files if p.startswith(target)]
            return '\n'.join(sorted(results)) if results else ''
        else:
            return f'sh: {cmd}: command not found'

    # Process $(cmd arg...) substitutions in the template
    # This is the vulnerable pattern: user-controlled template is executed
    def _substitute(m):
        return _exec_cmd(m.group(1))

    rendered = re.sub(r'\$\(([^)]+)\)', _substitute, template)

    body = (
        '--- PDF REPORT ---\n'
        + rendered
        + '\n--- END OF REPORT ---'
    )
    return 200, {'Content-Type': 'text/plain'}, body
